@startuml

class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : string
}

class PolicyType {
  + TypeName : string
  + Description : string
}

class Policy {
  + PolicyNumber : string
  + CoverageAmount : double
}

class Customer {
  + CustomerId : int
  + Name : string
  + Email : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "0..*" Policy
InsuranceCompany "1" -- "0..*" Customer
Customer "1" -- "0..*" Contract
Contract "0..*" -- "1" Policy
Policy "1" -- "1" PolicyType

@enduml

